            if (word in stopwords) stopwordCount++
            else if (word.length == 1) shortCount++
            else words.add(word)
        }
        for (i in 1 until words.size) bigrams.add(words[i - 1] + "_" + words[i])
        bigramTerms = words + bigrams
    }
